solution.simple_linked_list.zig:
const std = @import("std");
pub const Node = struct { value: i64, next: ?*Node = null };
pub const LinkedList = struct {
    allocator: std.mem.Allocator,
    head: ?*Node = null,
    len: usize = 0,
    pub fn init(a: std.mem.Allocator, values: []const i64) !LinkedList {
        var l = LinkedList{ .allocator = a };
        errdefer l.deinit();
        for (values) |v| try l.push(v);
        return l;
    }
    pub fn deinit(l: *LinkedList) void {
        while (l.head != null) {
            _ = l.pop() catch unreachable;
        }
    }
    pub fn push(l: *LinkedList, v: i64) !void {
        const n = try l.allocator.create(Node);
        n.* = .{ .value = v, .next = l.head };
        l.head = n;
        l.len += 1;
    }
    pub fn pop(l: *LinkedList) !i64 {
        const n = l.head orelse return error.EmptyList;
        const v = n.value;
        l.head = n.next;
        l.len -= 1;
        l.allocator.destroy(n);
        return v;
    }
    pub fn peek(l: LinkedList) !i64 {
        return (l.head orelse return error.EmptyList).value;
    }
    pub fn reverse(l: *LinkedList) void {
        var prev: ?*Node = null;
        var cur = l.head;
        while (cur) |n| {
            const next = n.next;
            n.next = prev;
            prev = n;
            cur = next;
        }
        l.head = prev;
    }

    pub fn headNode(l: LinkedList) !*const Node {
        return l.head orelse error.EmptyList;
    }
    pub const Iterator = struct {
        current: ?*const Node,
        pub fn next(it: *Iterator) ?i64 {
            const n = it.current orelse return null;
            it.current = n.next;
            return n.value;
        }
    };
    pub fn iterator(l: LinkedList) Iterator {
        return .{ .current = l.head };
    }
    pub fn reversed(l: LinkedList, a: std.mem.Allocator) !LinkedList {
        var out = try LinkedList.init(a, &.{});
        errdefer out.deinit();
        var it = l.iterator();
        while (it.next()) |value| try out.push(value);
        return out;
    }
    pub fn toSlice(l: LinkedList, a: std.mem.Allocator) ![]i64 {
        const s = try a.alloc(i64, l.len);
        var cur = l.head;
        for (s) |*v| {
            v.* = cur.?.value;
            cur = cur.?.next;
        }
        return s;
    }
};

